h = rand(@ptnum * 3.17 + 0.5)
big = @floors >= 5
s@name = where(big & (h < 0.035), "Roof_Tank", where(h < 0.14, "Roof_Unit", ""))
# random quarter turns and a little slack inside the 4 m cell
a = floor(rand(@ptnum * 1.91) * 4) * 1.5708
@N = set(sin(a), 0, cos(a))
@P.x += (rand(@ptnum * 2.3) - 0.5) * 1.2
@P.z += (rand(@ptnum * 4.1) - 0.5) * 1.2

@pscale = 0.7 + 0.35 * rand(@ptnum * 3.3)
t = rand(@ptnum * 7.7)
# darker low and inside the crown, sunlit yellow-greens on top
hgt = smoothstep(3.8, 6.3, @P.y)
v@leaf = lerp(set(0.13, 0.22, 0.08), set(0.30, 0.42, 0.14), 0.25 * t + 0.75 * hgt)
@N = set(sin(@ptnum * 2.1), 0, cos(@ptnum * 2.1))
@up = set(0, 1, 0)

along_z = abs(@P.x) < abs(@P.z)       # on a curb that runs along z
k = floor(abs(where(along_z, @P.z, @P.x)) / 6)
s@name = where(k % 2 == 0, "lamp", "tree")
tree = k % 2 == 1
a = rand(@ptnum * 5.3) * 6.2832
face = where(along_z, set(-np.sign(@P.x), 0, 0), set(0, 0, -np.sign(@P.z)))
@N = where(tree, set(sin(a), 0, cos(a)), face)
@up = set(0, 1, 0)
@pscale = where(tree, 0.8 + 0.45 * rand(@ptnum * 1.7), 1.0)

along_z = abs(@P.x) < abs(@P.z)
h = rand(@ptnum * 2.71 + 0.3)
@keep = h < 0.62
# drive on the right: the car heads along the traffic on its side of the street
d = where(along_z, -np.sign(@P.x), np.sign(@P.z))
@N = where(along_z, set(0, 0, 1) * d, set(1, 0, 0) * d)
@N = set(@N.z, 0, -@N.x)   # the car model is long in x: turn it to face along N
@up = set(0, 1, 0)
@P += @N * (rand(@ptnum * 9.1) - 0.5) * 0.6
s@name = "car"
@pscale = 1
c = rand(@ptnum * 6.13)
v@paint = where(c < 0.25, set(0.80, 0.80, 0.78), where(c < 0.45, set(0.06, 0.06, 0.07), where(c < 0.6, set(0.42, 0.44, 0.46), where(c < 0.72, set(0.55, 0.08, 0.06), where(c < 0.84, set(0.10, 0.18, 0.38), set(0.25, 0.30, 0.20))))))

s@name = "tree"
a = rand(@ptnum * 3.7 + 0.2) * 6.2832
@N = set(sin(a), 0, cos(a))
@up = set(0, 1, 0)
@pscale = 0.9 + 0.8 * rand(@ptnum * 2.3 + 0.7)

top = @N.y > 0.5
s@material = where(top, "M_RoofFlat", where(@far == 0, "M_FacadeFar", "M_FacadeFarBrick"))
@Cd = where(top, set(0.36, 0.36, 0.36), where(@far == 0, set(0.66, 0.60, 0.51), set(0.52, 0.30, 0.22)))

order = np.array(["Wall_Plain", "Wall_Window", "Wall_WindowPair", "Wall_Door", "Wall_Balcony", "Wall_Shopfront", "Corner_Pillar", "Roof_Cornice", "Roof_Flat", "Roof_Unit", "Roof_Tank"])
s@name = order[@ptnum]
@N = set(0, 0, 1)
@up = set(0, 1, 0)
